#include <bits/stdc++.h>using namespace std;#define int long longinline void fmx(int &a,int b){ if(a<b) a=b;}#define go(i,a,b) for(int i=a;i<=b;i++)#define og(i,a,b) for(int i=b;i>=a;i--)#define all() a.begin() + 1,a.begin() + n + 1const int inf = 0x3f3f3f3f3f3f3f;int T,n,k,x,y; void O_o(){    cin >> n >> k >> x >> y;    vector<int> a(n + 1,0),b(n + 1,0),c(n + 1,0),preb(n + 1,0),prec(n + 1,0),pred(n + 1);    for(int i=1;i<=n;i++){        cin >> a[i];        b[i] = a[i] % x;        c[i] = a[i] % y % x;    }    for(int i=1;i<=n;i++){        preb[i] = preb[i - 1] + b[i];        prec[i] = prec[i - 1] + c[i];        pred[i] = pred[i - 1] + min(b[i],c[i]);    }    // [l,l+k-1] -> pre[i + k - 1] - pre[l - 1] <=> inside    // [1,l-1] + [r+1,n] -> pre[l-1] - pre[0] + pre[n] - pre[r] <=> outside    int ans = inf;    for(int l=1;;l++){        int r = l + k - 1;        if(r > n)break;        int inside = min(preb[r] - preb[l - 1],prec[r] - prec[l - 1]);        int outside = pred[l - 1] + pred[n] - pred[r];        ans = min(ans,inside + outside);    }    cout << ans << '\n';} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);cout.tie(nullptr);    cin >> T;    while(T--)O_o();}